{"command":"python3 - <<'PY'
from pathlib import Path
p=Path('tcc_compat.py')
s=p.read_text()
# Insert compose function after handle_dM
marker='''def gcc_predefine_args(options: Options, base_file: str) -> List[str]:\n'''
insert=r'''
def command_macro_lines(options: Options) -> List[str]:
    lines: List[str] = []
    for kind, val in options.pp_cmds:
        if kind == "D":
            lines.append(define_to_line(val))
        else:
            lines.append("#undef " + val)
    return lines


def compose_dD_output(options: Options, display: str, preprocessed: str, source_text: str) -> str:
    macros = builtin_macro_lines(options.std, display) + command_macro_lines(options) + scan_defines_from_text(source_text)
    if options.line_mode == 0:
        parts = macros + preprocessed.splitlines()
        return "\n".join(parts) + ("\n" if parts else "")
    lines = preprocessed.splitlines()
    if options.line_mode == 1:
        # Expected header is: #line 1 file, #line 1 <command line>, #line 1 file
        if len(lines) >= 3 and lines[0].startswith('#line ') and '<command line>' in lines[1]:
            parts = [lines[0], lines[1]] + macros + [lines[2]] + lines[3:]
        else:
            parts = [f'#line 1 "{display}"', '#line 1 "<command line>"'] + macros + [f'#line 1 "{display}"'] + lines
        return "\n".join(parts) + ("\n" if parts else "")
    # Default # marker mode.  Insert command-line macro definitions in the command-line block.
    if len(lines) >= 3 and lines[0].startswith('# 1 ') and '<command line>' in lines[1]:
        parts = [lines[0], lines[1]] + macros + [lines[2]] + lines[3:]
    else:
        parts = [f'# 1 "{display}"', '# 1 "<command line>" 1'] + macros + [f'# 1 "{display}" 2'] + lines
    return "\n".join(parts) + ("\n" if parts else "")

'''
if marker not in s:
    raise SystemExit('marker not found')
s=s.replace(marker, insert+marker)
# Remove appending -dD in run_cpp
s=s.replace('''    if options.dD:\n        cmd.append("-dD")\n    cmd += gcc_predefine_args(options, display)\n''','''    # -dD output is synthesized below to avoid leaking host-compiler built-ins.\n    cmd += gcc_predefine_args(options, display)\n''')
# Replace input read block and after postprocess to include source_text
old='''    if inp == "-":\n        cmd.append("-")\n        data = sys.stdin.buffer.read()\n        proc = subprocess.run(cmd, input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    else:\n        cmd.append(inp)\n        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n\n    out_text = proc.stdout.decode(errors="replace")\n    err_text = transform_stderr_common(proc.stderr.decode(errors="replace"))\n    out_text = postprocess_cpp_output(out_text, display, options.line_mode)\n\n    if options.verbose:\n'''
new='''    source_text = ""\n    if inp == "-":\n        cmd.append("-")\n        data = sys.stdin.buffer.read()\n        source_text = data.decode(errors="ignore")\n        proc = subprocess.run(cmd, input=data, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n    else:\n        try:\n            source_text = Path(inp).read_text(errors="ignore")\n        except OSError:\n            source_text = ""\n        cmd.append(inp)\n        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)\n\n    out_text = proc.stdout.decode(errors="replace")\n    err_text = transform_stderr_common(proc.stderr.decode(errors="replace"))\n    out_text = postprocess_cpp_output(out_text, display, options.line_mode)\n    if options.dD and proc.returncode == 0:\n        out_text = compose_dD_output(options, display, out_text, source_text)\n\n    if options.verbose:\n'''
if old not in s:
    raise SystemExit('block not found')
s=s.replace(old,new)
p.write_text(s)
PY
